import { type Module, type ModuleMetadata } from '@divi/types';
/**
 * Generate Default Attrs.
 *
 * Generates default attributes from module metadata's (module.json) attributes. It can be generate
 * `default` or `defaultPrintedStyle` attributes for the module.
 *
 * @since ??
 *
 * @param {object} moduleMetadata Module metadata (module.json).
 * @param {string} defaultPropName The name of the default property to use. Defaults to 'default'.
 *
 * @returns {object} The generated default attributes for the module.
 *
 * @example
 * ```tsx
 * const moduleMetadata = {
 *  attributes: {
 *   attr1: {
 *    type: 'object',
 *    default: {
 *     value: 'default value',
 *    },
 *    defaultPrintedStyle: {
 *     value: 'default printed style value',
 *    },
 *   },
 *  }
 * };
 * generateDefaultAttrs(moduleMetadata);
 * // => { attr1: { value: 'default value' } }
 * ```
 * @example
 * ```tsx
 * const moduleMetadata = {
 *  attributes: {
 *   attr1: {
 *    type: 'object',
 *    default: {
 *     value: 'default value',
 *    },
 *    defaultPrintedStyle: {
 *     value: 'default printed style value',
 *    },
 *   },
 *  }
 * };
 * generateDefaultAttrs(moduleMetadata, 'defaultPrintedStyle');
 * // => { attr1: { value: 'default printed style value' } }
 * ```
 */
export declare const generateDefaultAttrs: (moduleMetadata: ModuleMetadata, defaultPropName?: 'default' | 'defaultPrintedStyle') => Record<string, Module.Element.Attributes>;
